<script setup lang="ts">
import {ref} from 'vue';import {useWorkbench} from '../stores/workbench';import UiIcon from './UiIcon.vue';import StatusBadge from './StatusBadge.vue';const s=useWorkbench(),tryBuild=ref(true);const names=['规格合法','结构一致','数据检查','可执行检查','语义回译'];const levels=(n:number)=>(s.check?.findings||[]).filter((f:any)=>Number(f.layer)===n);function state(n:number){const f=levels(n);return f.some((x:any)=>x.severity==='error')?'error':f.some((x:any)=>x.severity==='warning'||x.severity==='warn')?'warning':'pass';}function locate(f:any){if(f.item_id){s.focusId=f.item_id;s.tab='spec';s.step=3;}}
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M4 / 原文依据 · 对象存在 · 覆盖检查</div><h2>五层去幻觉校验</h2></div><div class="actions"><el-checkbox v-model="tryBuild">试构建 T = 1</el-checkbox><el-button type="primary" :loading="s.busy" @click="s.validate(tryBuild).catch(()=>{})" data-testid="run-check">运行五层校验</el-button></div></div><div class="notice">试构建只验证 Pyomo 模型能否构建；不代表原始数据满足交流潮流方程，也不代表交流 N−1 校核通过。</div><template v-if="s.check"><div class="check-overview"><div><strong :class="s.check.errors?'text-danger':'text-success'">{{s.check.errors?'发现 '+s.check.errors+' 项错误':'未发现阻断错误'}}</strong><span>{{s.check.warnings}} 项警告 · 警告需人工确认</span></div><span v-if="s.check.errors" class="inference-tag">请返回规格修正</span></div><details v-for="(name,i) in names" :key="name" class="check-layer" :open="state(i+1)!=='pass'"><summary class="layer-title"><span class="layer-light" :class="state(i+1)"></span><span class="layer-index">0{{i+1}}</span><h3>{{name}}</h3><span class="small-note">{{levels(i+1).length}} 项记录</span></summary><button v-for="(f,j) in levels(i+1)" :key="j" class="finding-row" :class="f.severity" @click="locate(f)"><span class="finding-code" :class="f.severity">{{f.code}}</span><div><strong>{{f.message}}</strong><small v-if="f.suggestion">建议：{{f.suggestion}}</small></div><span v-if="f.item_id" class="finding-target">{{f.item_id}} ↗</span></button><div v-if="!levels(i+1).length" class="layer-clear">本层未报告问题。</div></details><section v-if="s.check.back_translation" class="soft-panel panel-pad"><h3>语义回译</h3><div class="two-columns"><div><span class="small-note">调度指令原文</span><p>{{s.spec.instruction}}</p></div><div><span class="small-note">规格回译</span><p v-if="typeof s.check.back_translation==='string'">{{s.check.back_translation}}</p><p v-else v-for="(t,i) in s.check.back_translation" :key="i">{{typeof t==='string'?t:t.text||t.message||JSON.stringify(t)}}</p></div></div></section><div class="notice"><UiIcon name="info"/><span>铮昊外部去幻觉方法 <StatusBadge name="铮昊方法"/> · {{s.integrations.find(i=>i.id==='method')?.endpoint?'已配置接口':'未接入'}}</span></div><div v-if="s.check.build" class="build-summary"><details><summary>试构建与规模证据</summary><pre class="json-block">{{JSON.stringify(s.check.build,null,2)}}</pre></details></div><div class="panel-bottom-actions"><el-button @click="s.step=3;s.tab='spec'">返回规格修改</el-button><div class="check-path-actions"><el-button :disabled="!!s.check.errors||!s.confirmed" @click="s.step=5" data-testid="go-solver">进入求解黑盒</el-button><el-button type="primary" :disabled="!!s.check.errors||!s.confirmed" :loading="s.busy" @click="s.evaluate().catch(()=>{})" data-testid="go-baseline-risk">基态风险与协商 <UiIcon name="arrow" :size="15"/></el-button></div></div><p v-if="s.confirmed&&!s.check.errors" class="small-note">可直接评估调整前断面并协商模型，也可先通过黑盒导入求解结果。</p><p v-if="!s.confirmed" class="small-note">请先在规格页确认并保存版本，再进入求解。</p></template><div v-else class="inline-empty large"><UiIcon name="shield" :size="40"/><h3>校验报告尚未生成</h3><p>运行五层检查，逐项核对规格、结构、数据、可执行性与语义覆盖。</p></div></div></template>